  \coordinate (v2) at (1,1,1);
  \coordinate (u2) at (0,0,1);

  \begin{scope}[x=(v1), y=(u2), transformxy]
    \fill[seq-violet!50, opacity=.7] (-1,-1) rectangle (2.3,2);
