    \coordinate (p32) at (0,1);
  \end{scope}

  \point (o) at (0,0,0);
  \draw[vector, black!50] (o) -- node[auto,swap] {$u_1$} (u1);
  \draw[vector, black!50] (o) -- node[auto] {$u_2$} (u2);
  \pic[draw] {right angle=(u1)--(o)--(u2)};

