  \draw[vector] (o) -- node[sloped,midway,above=1pt]
    {$(v_3)_{W_2}$} (p3);
  \pic[draw] {right angle=(o)--(p3)--(v3)};
  \draw[very thin, black!50] (p3) -- (p31);
  \draw[very thin, black!50] (p3) -- (p32);

